"use client";

import { useState } from "react";
import StatCards from "@/components/dashboard/StatCards";
import DomainTable from "@/components/dashboard/DomainTable";
import AlertsFeed from "@/components/dashboard/AlertsFeed";
import HealthChart from "@/components/dashboard/HealthChart";
import ComplianceBreakdown from "@/components/dashboard/ComplianceBreakdown";
import AddDomainWizard from "@/components/dashboard/AddDomainWizard";

export default function DashboardPage() {
  const [showWizard, setShowWizard] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);

  function handleDomainAdded(domain: string) {
    // Increment key to force DomainTable to re-fetch
    setRefreshKey((k) => k + 1);
    console.log("Domain added:", domain);
  }

  return (
    <>
      {/* Add Domain Wizard */}
      {showWizard && (
        <AddDomainWizard
          onClose={() => setShowWizard(false)}
          onDomainAdded={handleDomainAdded}
        />
      )}

      {/* Stat cards */}
      <StatCards />

      {/* Main grid */}
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 310px",
          gap: 20,
          alignItems: "start",
        }}
      >
        {/* Domain table */}
        <DomainTable key={refreshKey} onAddDomain={() => setShowWizard(true)} />

        {/* Right column */}
        <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
          <HealthChart />
          <AlertsFeed />
          <ComplianceBreakdown />
        </div>
      </div>
    </>
  );
}
