// A multi-step wizard for adding a new domain:
// Step 1 — Enter domain name
// Step 2 — Running DNS checks (live results streaming in)
// Step 3 — Compliance report with AI diagnosis
// Step 4 — Setup complete, next steps

"use client";

import { useState } from "react";
import {
  CheckCircle,
  XCircle,
  AlertCircle,
  RefreshCw,
  X,
  ArrowRight,
  Copy,
  Check,
} from "lucide-react";
import { useApi } from "@/lib/api";

// ─────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────

interface DnsCheckResult {
  domain: string;
  overallScore: number;
  spf: {
    result: string;
    lookupCount: number;
    record: string | null;
    issues: string[];
  };
  dkim: Array<{
    selector: string;
    valid: boolean;
    keyBits: number;
    keyType: string;
    issues: string[];
  }>;
  dmarc: {
    result: string;
    policy: string;
    record: string | null;
    ruaAddresses: string[];
    issues: string[];
  };
  softFailures: string[];
}

interface Props {
  onClose: () => void;
  onDomainAdded: (domain: any) => void;
}

// ─────────────────────────────────────────────
// STEP INDICATOR
// ─────────────────────────────────────────────

function StepIndicator({ current, total }: { current: number; total: number }) {
  return (
    <div className="flex items-center gap-2">
      {Array.from({ length: total }).map((_, i) => (
        <div
          key={i}
          style={{
            height: 4,
            width: i < current ? 32 : 20,
            borderRadius: 999,
            background:
              i < current
                ? "linear-gradient(135deg, #2563EB, #7C3AED)"
                : "var(--border)",
            transition: "all 0.3s",
          }}
        />
      ))}
    </div>
  );
}

// ─────────────────────────────────────────────
// STATUS ICON
// ─────────────────────────────────────────────

function StatusIcon({ status, size = 16 }: { status: string; size?: number }) {
  if (status === "pass") return <CheckCircle size={size} color="#10B981" />;
  if (status === "fail" || status === "missing" || status === "none")
    return <XCircle size={size} color="#EF4444" />;
  return <AlertCircle size={size} color="#F59E0B" />;
}

// ─────────────────────────────────────────────
// SCORE RING
// ─────────────────────────────────────────────

function ScoreRing({ score }: { score: number }) {
  const color = score >= 80 ? "#10B981" : score >= 60 ? "#F59E0B" : "#EF4444";

  const circumference = 2 * Math.PI * 28;
  const progress = (score / 100) * circumference;

  return (
    <div style={{ position: "relative", width: 80, height: 80 }}>
      <svg width="80" height="80" style={{ transform: "rotate(-90deg)" }}>
        {/* Track */}
        <circle
          cx="40"
          cy="40"
          r="28"
          fill="none"
          stroke="var(--border)"
          strokeWidth="6"
        />
        {/* Progress */}
        <circle
          cx="40"
          cy="40"
          r="28"
          fill="none"
          stroke={color}
          strokeWidth="6"
          strokeDasharray={`${progress} ${circumference}`}
          strokeLinecap="round"
          style={{ transition: "stroke-dasharray 0.8s ease" }}
        />
      </svg>
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <span
          style={{
            fontSize: 20,
            fontWeight: 800,
            fontFamily: "var(--font-mono)",
            color,
          }}
        >
          {score}
        </span>
        <span style={{ fontSize: 9, color: "var(--text-3)", fontWeight: 600 }}>
          /100
        </span>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────
// SCANNING ANIMATION ROW
// Shows a pulsing placeholder while check is running
// ─────────────────────────────────────────────

function ScanningRow({ label }: { label: string }) {
  return (
    <div
      className="flex items-center gap-3"
      style={{
        padding: "12px 0",
        borderBottom: "1px solid var(--border)",
      }}
    >
      <div
        style={{
          width: 24,
          height: 24,
          borderRadius: "50%",
          border: "2px solid var(--border)",
          borderTopColor: "#2563EB",
          animation: "spin 1s linear infinite",
        }}
      />
      <div
        style={{
          flex: 1,
          height: 14,
          background: "var(--border)",
          borderRadius: 7,
          animation: "pulse 1.5s ease-in-out infinite",
        }}
      />
      <span style={{ fontSize: 12, color: "var(--text-3)" }}>{label}</span>
    </div>
  );
}

// ─────────────────────────────────────────────
// RESULT ROW
// Shows an actual DNS check result
// ─────────────────────────────────────────────

function ResultRow({
  label,
  status,
  detail,
  issues,
}: {
  label: string;
  status: string;
  detail?: string;
  issues?: string[];
}) {
  const [expanded, setExpanded] = useState(false);
  const hasIssues = issues && issues.length > 0;

  return (
    <div style={{ borderBottom: "1px solid var(--border)" }}>
      <div
        className="flex items-center gap-3"
        style={{
          padding: "13px 0",
          cursor: hasIssues ? "pointer" : "default",
        }}
        onClick={() => hasIssues && setExpanded(!expanded)}
      >
        <StatusIcon status={status} size={18} />

        <div style={{ flex: 1 }}>
          <p style={{ fontSize: 13.5, fontWeight: 600, color: "var(--text)" }}>
            {label}
          </p>
          {detail && (
            <p
              style={{
                fontSize: 11.5,
                color: "var(--text-3)",
                fontFamily: "var(--font-mono)",
                marginTop: 2,
                maxWidth: 340,
                overflow: "hidden",
                textOverflow: "ellipsis",
                whiteSpace: "nowrap",
              }}
            >
              {detail}
            </p>
          )}
        </div>

        {/* Status badge */}
        <span
          style={{
            fontSize: 11.5,
            fontWeight: 700,
            padding: "3px 9px",
            borderRadius: 999,
            background:
              status === "pass"
                ? "rgba(16,185,129,0.1)"
                : status === "fail" || status === "missing" || status === "none"
                  ? "rgba(239,68,68,0.1)"
                  : "rgba(245,158,11,0.1)",
            color:
              status === "pass"
                ? "#10B981"
                : status === "fail" || status === "missing" || status === "none"
                  ? "#EF4444"
                  : "#F59E0B",
          }}
        >
          {status.toUpperCase()}
        </span>

        {hasIssues && (
          <span
            style={{
              fontSize: 10,
              color: "var(--text-3)",
              transform: expanded ? "rotate(180deg)" : "rotate(0)",
              transition: "transform 0.2s",
              display: "inline-block",
            }}
          >
            ▼
          </span>
        )}
      </div>

      {/* Issues expanded */}
      {expanded && hasIssues && (
        <div
          style={{
            padding: "0 0 12px 32px",
            display: "flex",
            flexDirection: "column",
            gap: 6,
          }}
        >
          {issues!.map((issue, i) => (
            <div key={i} className="flex items-start gap-2">
              <AlertCircle
                size={12}
                color="#F59E0B"
                style={{ flexShrink: 0, marginTop: 2 }}
              />
              <p
                style={{
                  fontSize: 12.5,
                  color: "var(--text-2)",
                  lineHeight: 1.5,
                }}
              >
                {issue}
              </p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ─────────────────────────────────────────────
// MAIN WIZARD COMPONENT
// ─────────────────────────────────────────────

export default function AddDomainWizard({ onClose, onDomainAdded }: Props) {
  const { post, streamAnalysis } = useApi();

  // Wizard state
  const [step, setStep] = useState<1 | 2 | 3 | 4>(1);
  const [domain, setDomain] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // Scan results
  const [dnsResult, setDnsResult] = useState<DnsCheckResult | null>(null);
  const [aiDiagnosis, setAiDiagnosis] = useState("");
  const [scanComplete, setScanComplete] = useState(false);
  const [addedDomain, setAddedDomain] = useState<any>(null);

  // Scan progress — tracks which checks are done
  const [progress, setProgress] = useState({
    domainAdded: false,
    spfDone: false,
    dkimDone: false,
    dmarcDone: false,
    aiDone: false,
  });

  // Copy to clipboard state
  const [copied, setCopied] = useState(false);

  // ── Step 1 → Step 2: Add domain and start scan ──
  async function handleAddDomain() {
    // Validate domain format
    const cleaned = domain
      .trim()
      .toLowerCase()
      .replace(/^https?:\/\//, "")
      .replace(/\/.*$/, "");

    if (!cleaned || !cleaned.includes(".")) {
      setError("Please enter a valid domain name e.g. acme.com");
      return;
    }

    setError("");
    setLoading(true);

    try {
      // Add the domain via API
      const response = await post<{ data: any }>("/domains", {
        domain: cleaned,
      });

      setAddedDomain(response.data);
      setProgress((p) => ({ ...p, domainAdded: true }));
      setStep(2);

      // Start streaming the DNS analysis
      startAnalysis(cleaned);
    } catch (err: any) {
      setError(err.message || "Failed to add domain. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  // ── Start the streaming DNS analysis ──
  function startAnalysis(domainName: string) {
    let aiText = "";

    streamAnalysis(
      domainName,

      // DNS result arrived — update progress and results
      (result: DnsCheckResult) => {
        setDnsResult(result);
        setProgress((p) => ({
          ...p,
          spfDone: true,
          dkimDone: true,
          dmarcDone: true,
        }));
      },

      // AI token arrived — append to diagnosis
      (token: string) => {
        aiText += token;
        setAiDiagnosis(aiText);
      },

      // Analysis complete
      () => {
        setProgress((p) => ({ ...p, aiDone: true }));
        setScanComplete(true);
        // Auto-advance to results after a short delay
        setTimeout(() => setStep(3), 600);
      },

      // Error
      (err: string) => {
        console.error("Analysis error:", err);
        setScanComplete(true);
        setTimeout(() => setStep(3), 600);
      },
    );
  }

  // ── Copy unsubscribe header snippet ──
  function copySnippet() {
    const snippet =
      `List-Unsubscribe: <https://unsub.inboxrules.io/${addedDomain?.id}>, ` +
      `<mailto:unsubscribe@${domain}?subject=unsubscribe>\n` +
      `List-Unsubscribe-Post: List-Unsubscribe=One-Click`;

    navigator.clipboard.writeText(snippet);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  // ── Score color ──
  const score = dnsResult?.overallScore ?? 0;
  const scoreColor =
    score >= 80 ? "#10B981" : score >= 60 ? "#F59E0B" : "#EF4444";

  return (
    // Modal backdrop
    <div
      style={{
        position: "fixed",
        inset: 0,
        background: "rgba(0,0,0,0.6)",
        backdropFilter: "blur(6px)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        zIndex: 100,
        padding: 24,
      }}
      onClick={onClose}
    >
      {/* Modal container */}
      <div
        style={{
          background: "var(--surface)",
          border: "1px solid var(--border)",
          borderRadius: 20,
          width: "100%",
          maxWidth: 560,
          maxHeight: "90vh",
          display: "flex",
          flexDirection: "column",
          overflow: "hidden",
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* ── Modal Header ── */}
        <div
          style={{
            padding: "20px 24px",
            borderBottom: "1px solid var(--border)",
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <div>
            <div className="flex items-center gap-3">
              <h2
                style={{
                  fontSize: 17,
                  fontWeight: 800,
                  color: "var(--text)",
                  letterSpacing: "-0.3px",
                }}
              >
                {step === 1 && "Add New Domain"}
                {step === 2 && "Running Compliance Scan"}
                {step === 3 && "Compliance Report"}
                {step === 4 && "All Set!"}
              </h2>
            </div>
            <StepIndicator current={step} total={4} />
          </div>

          {/* Close button */}
          <button
            onClick={onClose}
            style={{
              width: 32,
              height: 32,
              borderRadius: 8,
              border: "1px solid var(--border)",
              background: "var(--surface-2)",
              cursor: "pointer",
              color: "var(--text-3)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <X size={14} />
          </button>
        </div>

        {/* ── Modal Body ── */}
        <div
          style={{
            flex: 1,
            overflowY: "auto",
            padding: "24px",
          }}
        >
          {/* ════════════════════════════
              STEP 1 — Enter Domain
          ════════════════════════════ */}
          {step === 1 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
              <p
                style={{
                  fontSize: 14,
                  color: "var(--text-2)",
                  lineHeight: 1.6,
                }}
              >
                Enter your sending domain and we will immediately run a full
                SPF, DKIM, and DMARC compliance check.
              </p>

              {/* Domain input */}
              <div>
                <label
                  style={{
                    display: "block",
                    fontSize: 13,
                    fontWeight: 600,
                    color: "var(--text-2)",
                    marginBottom: 8,
                  }}
                >
                  Domain Name
                </label>
                <input
                  type="text"
                  value={domain}
                  onChange={(e) => {
                    setDomain(e.target.value);
                    setError("");
                  }}
                  onKeyDown={(e) => e.key === "Enter" && handleAddDomain()}
                  placeholder="e.g. acme.com or mail.acme.com"
                  autoFocus
                  style={{
                    width: "100%",
                    height: 46,
                    padding: "0 16px",
                    background: "var(--surface-2)",
                    border: `1px solid ${error ? "#EF4444" : "var(--border)"}`,
                    borderRadius: 11,
                    fontSize: 15,
                    color: "var(--text)",
                    fontFamily: "var(--font-sans)",
                    outline: "none",
                  }}
                />
                {error && (
                  <p style={{ fontSize: 12.5, color: "#EF4444", marginTop: 6 }}>
                    {error}
                  </p>
                )}
              </div>

              {/* What we check */}
              <div
                style={{
                  background: "var(--surface-2)",
                  border: "1px solid var(--border)",
                  borderRadius: 12,
                  padding: 16,
                }}
              >
                <p
                  style={{
                    fontSize: 12,
                    fontWeight: 700,
                    color: "var(--text-3)",
                    marginBottom: 10,
                    textTransform: "uppercase",
                    letterSpacing: "0.07em",
                  }}
                >
                  What we check
                </p>
                {[
                  {
                    icon: "📋",
                    label: "SPF record",
                    desc: "Verifies lookup count and alignment",
                  },
                  {
                    icon: "🔑",
                    label: "DKIM selectors",
                    desc: "Checks 16 common selectors automatically",
                  },
                  {
                    icon: "🛡️",
                    label: "DMARC policy",
                    desc: "Validates policy and reporting setup",
                  },
                  {
                    icon: "⚡",
                    label: "AI diagnosis",
                    desc: "Plain-English explanation of issues",
                  },
                ].map((item) => (
                  <div
                    key={item.label}
                    className="flex items-center gap-3"
                    style={{ marginBottom: 8 }}
                  >
                    <span style={{ fontSize: 16, flexShrink: 0 }}>
                      {item.icon}
                    </span>
                    <div>
                      <span
                        style={{
                          fontSize: 13,
                          fontWeight: 600,
                          color: "var(--text)",
                        }}
                      >
                        {item.label}
                      </span>
                      <span
                        style={{
                          fontSize: 12,
                          color: "var(--text-3)",
                          marginLeft: 6,
                        }}
                      >
                        — {item.desc}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* ════════════════════════════
              STEP 2 — Scanning
          ════════════════════════════ */}
          {step === 2 && (
            <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
              {/* Domain being scanned */}
              <div
                style={{
                  padding: "12px 16px",
                  background: "rgba(37,99,235,0.06)",
                  border: "1px solid rgba(37,99,235,0.15)",
                  borderRadius: 10,
                  display: "flex",
                  alignItems: "center",
                  gap: 10,
                }}
              >
                <div
                  style={{
                    width: 8,
                    height: 8,
                    borderRadius: "50%",
                    background: "#2563EB",
                    animation: "pulse 1s ease-in-out infinite",
                  }}
                />
                <span
                  style={{
                    fontSize: 13.5,
                    fontWeight: 600,
                    color: "var(--text)",
                    fontFamily: "var(--font-mono)",
                  }}
                >
                  {domain}
                </span>
                <span style={{ fontSize: 12, color: "var(--text-3)" }}>
                  — scanning in progress
                </span>
              </div>

              {/* Check rows */}
              <div>
                {!progress.spfDone ? (
                  <ScanningRow label="Checking SPF..." />
                ) : (
                  <ResultRow
                    label={`SPF — ${dnsResult?.spf.lookupCount}/10 lookups`}
                    status={dnsResult?.spf.result || "unknown"}
                    detail={dnsResult?.spf.record || undefined}
                    issues={dnsResult?.spf.issues}
                  />
                )}

                {!progress.dkimDone ? (
                  <ScanningRow label="Checking DKIM..." />
                ) : (
                  <ResultRow
                    label={`DKIM — ${dnsResult?.dkim.length || 0} selector(s) found`}
                    status={
                      dnsResult?.dkim.some((d) => d.valid) ? "pass" : "fail"
                    }
                    detail={
                      dnsResult?.dkim.map((d) => d.selector).join(", ") ||
                      undefined
                    }
                    issues={dnsResult?.dkim
                      .flatMap((d) => d.issues)
                      .filter(Boolean)}
                  />
                )}

                {!progress.dmarcDone ? (
                  <ScanningRow label="Checking DMARC..." />
                ) : (
                  <ResultRow
                    label={`DMARC — p=${dnsResult?.dmarc.policy || "none"}`}
                    status={dnsResult?.dmarc.result || "unknown"}
                    detail={dnsResult?.dmarc.record || undefined}
                    issues={dnsResult?.dmarc.issues}
                  />
                )}

                {!progress.aiDone && (
                  <div
                    style={{
                      padding: "13px 0",
                      borderBottom: "1px solid var(--border)",
                      display: "flex",
                      alignItems: "center",
                      gap: 10,
                    }}
                  >
                    <RefreshCw
                      size={16}
                      color="#2563EB"
                      style={{ animation: "spin 1s linear infinite" }}
                    />
                    <span style={{ fontSize: 13, color: "var(--text-2)" }}>
                      AI is analyzing results...
                    </span>
                  </div>
                )}
              </div>

              {/* Soft failures */}
              {dnsResult?.softFailures.length ? (
                <div
                  style={{
                    background: "rgba(245,158,11,0.06)",
                    border: "1px solid rgba(245,158,11,0.2)",
                    borderRadius: 10,
                    padding: 14,
                  }}
                >
                  <p
                    style={{
                      fontSize: 12,
                      fontWeight: 700,
                      color: "#F59E0B",
                      marginBottom: 8,
                    }}
                  >
                    ⚠️ Soft Failures Detected
                  </p>
                  {dnsResult.softFailures.map((w, i) => (
                    <p
                      key={i}
                      style={{
                        fontSize: 12.5,
                        color: "var(--text-2)",
                        marginBottom: 6,
                        lineHeight: 1.5,
                      }}
                    >
                      · {w}
                    </p>
                  ))}
                </div>
              ) : null}
            </div>
          )}

          {/* ════════════════════════════
              STEP 3 — Full Report
          ════════════════════════════ */}
          {step === 3 && dnsResult && (
            <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
              {/* Score and summary */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 20,
                  padding: 20,
                  background: "var(--surface-2)",
                  border: "1px solid var(--border)",
                  borderRadius: 14,
                }}
              >
                <ScoreRing score={score} />

                <div style={{ flex: 1 }}>
                  <p
                    style={{
                      fontSize: 18,
                      fontWeight: 800,
                      color: scoreColor,
                      letterSpacing: "-0.3px",
                    }}
                  >
                    {score >= 80
                      ? "Looking good!"
                      : score >= 60
                        ? "Needs attention"
                        : "Critical issues found"}
                  </p>
                  <p
                    style={{
                      fontSize: 13.5,
                      fontFamily: "var(--font-mono)",
                      color: "var(--text-2)",
                      marginTop: 4,
                    }}
                  >
                    {domain}
                  </p>
                  <div
                    className="flex items-center gap-2"
                    style={{ marginTop: 10 }}
                  >
                    {[
                      { label: "SPF", status: dnsResult.spf.result },
                      {
                        label: "DKIM",
                        status: dnsResult.dkim.some((d) => d.valid)
                          ? "pass"
                          : "fail",
                      },
                      { label: "DMARC", status: dnsResult.dmarc.result },
                    ].map((item) => (
                      <div key={item.label} className="flex items-center gap-1">
                        <StatusIcon status={item.status} size={13} />
                        <span
                          style={{
                            fontSize: 12,
                            fontWeight: 600,
                            color: "var(--text-2)",
                          }}
                        >
                          {item.label}
                        </span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              {/* Check results */}
              <div
                style={{
                  background: "var(--surface-2)",
                  border: "1px solid var(--border)",
                  borderRadius: 12,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    padding: "14px 18px",
                    borderBottom: "1px solid var(--border)",
                  }}
                >
                  <p
                    style={{
                      fontSize: 13,
                      fontWeight: 700,
                      color: "var(--text)",
                    }}
                  >
                    Detailed Results
                  </p>
                </div>
                <div style={{ padding: "4px 18px" }}>
                  <ResultRow
                    label={`SPF — ${dnsResult.spf.lookupCount}/10 DNS lookups`}
                    status={dnsResult.spf.result}
                    detail={dnsResult.spf.record || undefined}
                    issues={dnsResult.spf.issues}
                  />
                  <ResultRow
                    label={`DKIM — ${dnsResult.dkim.length} selector(s)`}
                    status={
                      dnsResult.dkim.some((d) => d.valid) ? "pass" : "fail"
                    }
                    detail={dnsResult.dkim
                      .map((d) => `${d.selector} (${d.keyBits}-bit)`)
                      .join(", ")}
                    issues={dnsResult.dkim.flatMap((d) => d.issues)}
                  />
                  <ResultRow
                    label={`DMARC — p=${dnsResult.dmarc.policy}`}
                    status={dnsResult.dmarc.result}
                    detail={dnsResult.dmarc.record || undefined}
                    issues={dnsResult.dmarc.issues}
                  />
                </div>
              </div>

              {/* AI diagnosis */}
              {aiDiagnosis && (
                <div
                  style={{
                    background: "rgba(37,99,235,0.05)",
                    border: "1px solid rgba(37,99,235,0.15)",
                    borderRadius: 12,
                    padding: 18,
                  }}
                >
                  <p
                    style={{
                      fontSize: 12,
                      fontWeight: 700,
                      color: "#2563EB",
                      marginBottom: 12,
                      textTransform: "uppercase",
                      letterSpacing: "0.07em",
                    }}
                  >
                    🤖 AI Analysis
                  </p>
                  <div
                    style={{
                      fontSize: 13.5,
                      color: "var(--text-2)",
                      lineHeight: 1.7,
                      whiteSpace: "pre-wrap",
                    }}
                  >
                    {aiDiagnosis}
                  </div>
                </div>
              )}

              {/* Unsubscribe header snippet */}
              {addedDomain && (
                <div
                  style={{
                    background: "var(--surface-2)",
                    border: "1px solid var(--border)",
                    borderRadius: 12,
                    padding: 18,
                  }}
                >
                  <p
                    style={{
                      fontSize: 13,
                      fontWeight: 700,
                      color: "var(--text)",
                      marginBottom: 6,
                    }}
                  >
                    📧 Your List-Unsubscribe Headers
                  </p>
                  <p
                    style={{
                      fontSize: 12.5,
                      color: "var(--text-3)",
                      marginBottom: 12,
                      lineHeight: 1.5,
                    }}
                  >
                    Add these to every marketing email you send from {domain}
                    to comply with Gmail and Yahoo bulk sender requirements.
                  </p>
                  <div
                    style={{
                      background: "var(--surface)",
                      border: "1px solid var(--border)",
                      borderRadius: 8,
                      padding: "10px 14px",
                      position: "relative",
                    }}
                  >
                    <code
                      style={{
                        fontSize: 11.5,
                        fontFamily: "var(--font-mono)",
                        color: "var(--text-2)",
                        lineHeight: 1.8,
                        display: "block",
                        wordBreak: "break-all",
                      }}
                    >
                      List-Unsubscribe: {"<"}https://unsub.inboxrules.io/
                      {addedDomain.id}
                      {">"}, {"<"}mailto:unsubscribe@{domain}
                      ?subject=unsubscribe{">"}
                      <br />
                      List-Unsubscribe-Post: List-Unsubscribe=One-Click
                    </code>
                    <button
                      onClick={copySnippet}
                      style={{
                        position: "absolute",
                        top: 10,
                        right: 10,
                        width: 28,
                        height: 28,
                        borderRadius: 7,
                        border: "1px solid var(--border)",
                        background: "var(--surface)",
                        cursor: "pointer",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        color: copied ? "#10B981" : "var(--text-3)",
                      }}
                    >
                      {copied ? <Check size={12} /> : <Copy size={12} />}
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* ════════════════════════════
              STEP 4 — Complete
          ════════════════════════════ */}
          {step === 4 && (
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: 20,
                padding: "20px 0",
                textAlign: "center",
              }}
            >
              <div style={{ fontSize: 56 }}>🎉</div>

              <div>
                <h3
                  style={{
                    fontSize: 20,
                    fontWeight: 800,
                    color: "var(--text)",
                    marginBottom: 8,
                  }}
                >
                  {domain} is now being monitored
                </h3>
                <p
                  style={{
                    fontSize: 14,
                    color: "var(--text-2)",
                    lineHeight: 1.6,
                  }}
                >
                  InboxRules will check your DNS records every 6 hours and alert
                  you immediately if anything changes or breaks.
                </p>
              </div>

              {/* Next steps */}
              <div
                style={{
                  background: "var(--surface-2)",
                  border: "1px solid var(--border)",
                  borderRadius: 14,
                  padding: 20,
                  width: "100%",
                  textAlign: "left",
                }}
              >
                <p
                  style={{
                    fontSize: 12,
                    fontWeight: 700,
                    color: "var(--text-3)",
                    marginBottom: 14,
                    textTransform: "uppercase",
                    letterSpacing: "0.07em",
                  }}
                >
                  Recommended next steps
                </p>
                {[
                  {
                    icon: "📧",
                    title: "Add unsubscribe headers",
                    desc: "Copy the List-Unsubscribe headers to your email templates",
                  },
                  {
                    icon: "🔔",
                    title: "Set up Slack alerts",
                    desc: "Get notified in Slack when something breaks",
                  },
                  {
                    icon: "📊",
                    title: "Send a test email",
                    desc: "Use our analyzer to verify your setup end to end",
                  },
                ].map((step, i) => (
                  <div
                    key={i}
                    className="flex items-start gap-3"
                    style={{ marginBottom: 12 }}
                  >
                    <span style={{ fontSize: 18, flexShrink: 0 }}>
                      {step.icon}
                    </span>
                    <div>
                      <p
                        style={{
                          fontSize: 13.5,
                          fontWeight: 600,
                          color: "var(--text)",
                        }}
                      >
                        {step.title}
                      </p>
                      <p
                        style={{
                          fontSize: 12.5,
                          color: "var(--text-3)",
                          marginTop: 2,
                        }}
                      >
                        {step.desc}
                      </p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* ── Modal Footer ── */}
        <div
          style={{
            padding: "16px 24px",
            borderTop: "1px solid var(--border)",
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            background: "var(--surface-2)",
          }}
        >
          {/* Back / Cancel */}
          <button
            onClick={
              step === 1
                ? onClose
                : () => setStep((s) => Math.max(1, s - 1) as any)
            }
            style={{
              height: 38,
              padding: "0 16px",
              background: "transparent",
              border: "1px solid var(--border)",
              borderRadius: 10,
              fontSize: 13,
              fontWeight: 600,
              cursor: "pointer",
              color: "var(--text-2)",
              fontFamily: "var(--font-sans)",
            }}
          >
            {step === 1 ? "Cancel" : "← Back"}
          </button>

          {/* Primary action */}
          {step === 1 && (
            <button
              onClick={handleAddDomain}
              disabled={loading || !domain.trim()}
              className="flex items-center gap-2"
              style={{
                height: 38,
                padding: "0 20px",
                background:
                  loading || !domain.trim()
                    ? "var(--border)"
                    : "linear-gradient(135deg, #2563EB, #7C3AED)",
                color: loading || !domain.trim() ? "var(--text-3)" : "white",
                border: "none",
                borderRadius: 10,
                fontSize: 13,
                fontWeight: 600,
                cursor: loading || !domain.trim() ? "not-allowed" : "pointer",
                fontFamily: "var(--font-sans)",
                transition: "all 0.2s",
              }}
            >
              {loading ? (
                <>
                  <RefreshCw size={14} className="spin" />
                  Adding...
                </>
              ) : (
                <>
                  Start Scan
                  <ArrowRight size={14} />
                </>
              )}
            </button>
          )}

          {step === 2 && (
            <button
              onClick={() => {
                if (scanComplete) setStep(3);
              }}
              disabled={!scanComplete}
              className="flex items-center gap-2"
              style={{
                height: 38,
                padding: "0 20px",
                background: !scanComplete
                  ? "var(--border)"
                  : "linear-gradient(135deg, #2563EB, #7C3AED)",
                color: !scanComplete ? "var(--text-3)" : "white",
                border: "none",
                borderRadius: 10,
                fontSize: 13,
                fontWeight: 600,
                cursor: !scanComplete ? "not-allowed" : "pointer",
                fontFamily: "var(--font-sans)",
              }}
            >
              {scanComplete ? (
                <>
                  View Report <ArrowRight size={14} />
                </>
              ) : (
                <>
                  <RefreshCw size={14} className="spin" />
                  Scanning...
                </>
              )}
            </button>
          )}

          {step === 3 && (
            <button
              onClick={() => setStep(4)}
              className="flex items-center gap-2"
              style={{
                height: 38,
                padding: "0 20px",
                background: "linear-gradient(135deg, #2563EB, #7C3AED)",
                color: "white",
                border: "none",
                borderRadius: 10,
                fontSize: 13,
                fontWeight: 600,
                cursor: "pointer",
                fontFamily: "var(--font-sans)",
              }}
            >
              Continue <ArrowRight size={14} />
            </button>
          )}

          {step === 4 && (
            <button
              onClick={() => {
                onDomainAdded(addedDomain);
                onClose();
              }}
              className="flex items-center gap-2"
              style={{
                height: 38,
                padding: "0 20px",
                background: "linear-gradient(135deg, #10B981, #059669)",
                color: "white",
                border: "none",
                borderRadius: 10,
                fontSize: 13,
                fontWeight: 600,
                cursor: "pointer",
                fontFamily: "var(--font-sans)",
              }}
            >
              <CheckCircle size={14} />
              Go to Dashboard
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
